if ((!adcs_is_finite_vec3(sa_input.sun)) || (!adcs_is_finite_vec3(sa_input.boresight))) {
    sa_state.mode = SA_FAULT;
    sa_output.mode = SA_FAULT;
    return;
}

if ((!isfinite(sa_config.enter_cosine)) || (!isfinite(sa_config.exit_cosine)) ||
    (sa_config.exit_cosine < -1.0) || (sa_config.enter_cosine > 1.0) ||
    (sa_config.exit_cosine >= sa_config.enter_cosine)) {
    sa_state.mode = SA_FAULT;
    sa_output.mode = SA_FAULT;
    return;
}

if (adcs_vec3_normalize(sa_input.sun, ADCS_EPS_NORM, &sun_n) != ADCS_OK ||
    adcs_vec3_normalize(sa_input.boresight, ADCS_EPS_NORM, &bor_n) != ADCS_OK) {
    sa_state.mode = SA_FAULT;
    sa_output.mode = SA_FAULT;
    return;
}

cosine = adcs_vec3_dot(&sun_n, &bor_n);
if (!isfinite(cosine)) {
    sa_state.mode = SA_FAULT;
    sa_output.mode = SA_FAULT;
    return;
}
if (cosine > 1.0) cosine = 1.0;
if (cosine < -1.0) cosine = -1.0;

cross_v = adcs_vec3_cross(&sun_n, &bor_n);
cross_norm = adcs_vec3_norm(&cross_v);

sa_output.cosine = cosine;
sa_output.angle_rad = acos(cosine);
if (cross_norm > ADCS_EPS_COLLINEAR) {
    sa_output.correction_axis = adcs_vec3_scale(&cross_v, 1.0 / cross_norm);
} else {
    sa_output.correction_axis.x = 0.0;
    sa_output.correction_axis.y = 0.0;
    sa_output.correction_axis.z = 0.0;
}

cur = sa_state.mode;
if (cur == SA_FAULT) {
    next = SA_FAULT;
} else if (cur == SA_OFF) {
    if (cosine < sa_config.enter_cosine) next = SA_OFF;
    else next = SA_ACTIVE;
} else {
    if (cosine > sa_config.exit_cosine) next = SA_ACTIVE;
    else next = SA_OFF;
}

sa_state.mode = next;
sa_output.mode = next;
